"""Static audit of the scenarios (2026-11-24): reads the operation file of every simulation row of tests/usb20/testlist.csv (first
seed, regenerated) and reports patterns that let a scenario pass without checking what it claims:
  - checks: R (read with a mask), RS, RANY, P (poll), XD/XH/XT/XS (expected DUT packet), XN (no packet), XC, XP/WP (pins), MC
    (memory compare), GAP/GAPB, SOF/SOFW/SOFR/SOFD/SOFQ/NSOF/WSOF; stimulus: everything else
  - FLUSH: discards every DUT packet still queued, unchecked (an unexpected packet of the DUT is lost there)
  - bins without a check: a B (coverage bin) with no check operation since the previous B (the bin claims a scenario that was
    only stimulated)
  - weak checks: R/P with mask 0, SOF with an interval window wider than 10 microframes, XN shorter than 20 cycles,
    WP with the whole mask 0
    python env/scripts/ops_audit.py      -> sim/ops_audit.md, sim/ops_audit.csv"""
import csv
import os
import subprocess
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import vpaths as P  # noqa: E402

CHECK = {'R', 'RS', 'RANY', 'P', 'XD', 'XH', 'XT', 'XS', 'XN', 'XC', 'XP', 'WP', 'MC', 'GAP', 'GAPB', 'SOF', 'SOFW', 'SOFR', 'SOFD',
         'SOFQ', 'NSOF', 'WSOF', 'XR', 'DR', 'DX', 'AR', 'AW', 'AWS', 'AWJ', 'XK', 'TC', 'WS'}   # XK, TC, WS added 2026-11-25


def audit(path):
    st = dict(checks=0, stim=0, flush=0, bins=0, bins_nochk=[], weak=[])
    since = 0
    for n, ln in enumerate(open(path), 1):
        t = ln.split()
        if not t or t[0].startswith('#'):
            continue
        op = t[0]
        if op == 'B':
            st['bins'] += 1
            if since == 0:
                st['bins_nochk'].append(t[1])
            since = 0
            continue
        if op == 'FLUSH':
            st['flush'] += 1
            continue
        if op in CHECK:
            st['checks'] += 1
            since += 1
            v = [int(x, 16) for x in t[1:] if all(c in '0123456789abcdefABCDEF' for c in x)]
            if op in ('R', 'P') and len(v) >= 3 and v[2] == 0:
                st['weak'].append('%d:%s mask 0' % (n, op))
            if op == 'SOF' and len(v) >= 3 and v[2] - v[1] > 10 * 125000 / 1:
                st['weak'].append('%d:SOF window %d..%d ns' % (n, v[1], v[2]))
            if op == 'XN' and v and v[0] < 20:
                st['weak'].append('%d:XN %d cycles' % (n, v[0]))
            if op == 'WP' and len(v) >= 3 and v[2] == 0:
                st['weak'].append('%d:WP mask 0' % n)
        elif op not in ('END', 'CHK', 'WD', 'MSG', 'BP', 'SG', 'IPG', 'CLK'):
            st['stim'] += 1
    return st


def main():
    rows = [r for r in csv.DictReader(open(P.TESTLIST)) if r['kind'] == 'sim' and r['source'] != '-']
    out = []
    for r in rows:
        seed = r['seeds'].split()[0] if r['seeds'].strip() else '1'
        src = r['source'].split(':')
        g = subprocess.run([sys.executable, src[0], seed] + src[1:], cwd=P.TESTS, capture_output=True, text=True)
        if g.returncode != 0:
            continue
        ops = os.path.join(P.V, 'tests', g.stdout.strip().split('\n')[-1])
        s = audit(ops)
        out.append((r['test'], r['source'], s['checks'], s['stim'], s['flush'], s['bins'], len(s['bins_nochk']),
                    ' '.join(s['bins_nochk'][:8]), '; '.join(s['weak'][:6])))
    with open(os.path.join(P.SIMOUT, 'ops_audit.csv'), 'w', newline='') as f:
        w = csv.writer(f)
        w.writerow(['test', 'source', 'checks', 'stimulus', 'flush', 'bins', 'bins_without_check', 'examples', 'weak checks'])
        w.writerows(out)
    md = ['# Static scenario audit', '', 'Generated by `env/scripts/ops_audit.py` (see its docstring for the rules).', '',
          '| Test | Scenario | Checks | Stimulus | FLUSH | Bins | Bins without check | Examples | Weak checks |', '|---|---|---|---|---|---|---|---|---|']
    md += ['| %s |' % ' | '.join(str(x).replace('|', '/') for x in o) for o in out]
    open(os.path.join(P.SIMOUT, 'ops_audit.md'), 'w').write('\n'.join(md) + '\n')
    for o in out:
        print('%-22s %-34s chk=%-4d stim=%-4d flush=%-3d bins=%-3d nochk=%-3d %s | %s' % (o[0], o[1][:34], o[2], o[3], o[4], o[5], o[6], o[7][:60], o[8][:80]))
    return 0


if __name__ == '__main__':
    sys.exit(main())
